using Bodu.Security.Cryptography.Infrastructure;
namespace Bodu.Security.Cryptography;

/// <summary>
/// Contains unit tests for the <see cref="CubeHash" /> hash algorithm.
/// </summary>
[TestClass]
public partial class CubeHashTests
    : Security.Cryptography.HashAlgorithmTests<CubeHashTests, CubeHash, CubeHashVariants>
{
    private static readonly HashAlgorithmSpecification BaseCubeHashSpecification = new()
    {
        HashSize = 256,
        HashBlockSize = 32,
        LongInputLength = 200,
        MinNonZeroBytesForLongInput = null, // resolved from HashSize at runtime
        BoundaryLengths = [1, 8, 16, 64],
    };

    /// <summary>
    /// Verifies that constructing a <see cref="CubeHash"/> with an unsupported hash size throws
    /// <see cref="ArgumentOutOfRangeException"/> with the correct parameter name.
    /// </summary>
    [TestMethod]
    public void Ctor_WhenHashSizeIsUnsupported_ShouldThrowExactly()
    {
        ArgumentOutOfRangeException ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = new CubeHash(300);
        });
        Assert.AreEqual("hashSize", ex.ParamName);
    }

    /// <summary>
    /// Verifies that constructing a <see cref="CubeHash"/> with an out-of-range rounds value throws
    /// <see cref="ArgumentOutOfRangeException"/> with the correct parameter name.
    /// </summary>
    [TestMethod]
    public void Ctor_WhenRoundsIsOutOfRange_ShouldThrowExactly()
    {
        ArgumentOutOfRangeException ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = new CubeHash(16, 0, 32, 32, 512);
        });
        Assert.AreEqual("rounds", ex.ParamName);
    }

    /// <summary>
    /// Verifies that constructing a <see cref="CubeHash"/> with an out-of-range transform block size throws
    /// <see cref="ArgumentOutOfRangeException"/> with the correct parameter name.
    /// </summary>
    [TestMethod]
    public void Ctor_WhenTransformBlockSizeIsOutOfRange_ShouldThrowExactly()
    {
        ArgumentOutOfRangeException ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = new CubeHash(16, 16, 0, 32, 512);
        });
        Assert.AreEqual("transformBlockSize", ex.ParamName);
    }

